"use strict";

$(document).ready(function () {

    /* ===============================
       1. INIT DATATABLE (CUSTOM DOM)
    =============================== */
    const table = $("#leadList").DataTable({
        pageLength: 10,
        lengthMenu: [10, 20, 50, 100, 200, 500],
        dom:
            "<'row align-items-center mb-4 px-3'" +
            "<'col-md-6 d-flex align-items-center'l>" +
            "<'col-md-6 d-flex align-items-center justify-content-end'f<'bulk-actions ms-3'>>" +
            ">" +
            "t" +
            "<'row mt-3 px-3'" +
            "<'col-md-6'i>" +
            "<'col-md-6 d-flex justify-content-end'p>" +
            ">"
    });

    /* ===============================
       2. PINDAHKAN BULK BUTTON
    =============================== */
    if ($('#bulkActionWrapper').length) {
        $('.bulk-actions').append($('#bulkActionWrapper'));
    }

    /* ===============================
       3. CHECK ALL LEAD
    =============================== */
    $("#checkAllLead").on("change", function () {
        if (this.checked) {
            $(".checkbox").each(function () {
                this.checked = true;
                $(this).closest("tr").addClass("selected");
            });
        } else {
            $(".checkbox").each(function () {
                this.checked = false;
                $(this).closest("tr").removeClass("selected");
            });
        }
        toggleBulkButton();
    });

    /* ===============================
       4. SINGLE CHECKBOX
    =============================== */
    $(document).on("click", ".checkbox", function () {
        let allChecked = true;

        if ($(this).is(":checked")) {
            $(".checkbox").each(function () {
                if (!this.checked) allChecked = false;
            });
            if (allChecked) {
                $("#checkAllLead").prop("checked", true);
            }
        } else {
            $("#checkAllLead").prop("checked", false);
        }

        $(this).closest("tr").toggleClass("selected", this.checked);
        toggleBulkButton();
    });

    /* ===============================
       5. ROW HIGHLIGHT (KEEP OLD LOGIC)
    =============================== */
    $(".items-wrapper").on("click", "input:checkbox", function () {
        $(this).closest(".single-items").toggleClass("selected", this.checked);
    });

    $(".items-wrapper input:checkbox:checked")
        .closest(".single-items")
        .addClass("selected");

    /* ===============================
       6. BULK BUTTON VISIBILITY
    =============================== */
    function toggleBulkButton() {
        const checkedCount = $(".checkbox:checked").length;
        $("#bulkActionWrapper").toggleClass("d-none", checkedCount === 0);
    }

});
